"""Replayable commit checkpoints for offline coordination.

A checkpoint names an ``id``, the two 64-char lowercase hex digests of the
state and audit bytes it binds, and the ``stage`` the commit has reached.
Stages advance in the fixed order::

    prepared -> state -> audit -> committed

Checkpoints are kept in an index stored as UTF-8 compact JSON::

    {"items":[{"audit":...,"id":...,"stage":...,"state":...},...],"version":1}\\n

The top-level keys are fixed in the order ``items`` then ``version`` and
``version`` is always the integer 1.  ``items`` is an array of records
sorted ascending by ``id`` (ids are unique); each record carries the str
keys ``audit``, ``id``, ``stage`` and ``state`` in that order.  Non-ASCII
characters are preserved unescaped and the file ends with exactly one
``\\n``.

A missing index file stands for an empty index; an existing file that
violates any byte, structure, order or field rule is corrupt.

A brand-new id may only be recorded at the ``prepared`` stage.  Replaying
the same id with identical digests at the same stage is idempotent and
leaves the file bytes untouched; the stage may then advance one step at a
time, each advance replacing the file atomically.  Changed digests, a
stage regression or a skipped stage are rejected and never touch the file.
"""

from __future__ import annotations

import json
import os
import re
from typing import Any

AUDIT = "audit"
ID = "id"
STAGE = "stage"
STATE = "state"

ITEMS = "items"
VERSION = "version"

PREPARED = "prepared"
STAGE_STATE = "state"
STAGE_AUDIT = "audit"
COMMITTED = "committed"

_REQUEST_KEYS = (ID, STATE, AUDIT, STAGE)
_RECORD_KEYS = (AUDIT, ID, STAGE, STATE)
_INDEX_KEYS = (ITEMS, VERSION)
_INDEX_VERSION = 1

_STAGES = (PREPARED, STAGE_STATE, STAGE_AUDIT, COMMITTED)
_STAGE_RANK = {stage: rank for rank, stage in enumerate(_STAGES)}

_ID_RE = re.compile(r"[A-Za-z0-9._-]{1,64}\Z")
_DIGEST_RE = re.compile(r"[0-9a-f]{64}\Z")


class CorruptTransactionError(ValueError):
    """The checkpoint index exists but its bytes are not a valid index."""


def _is_digest(value: Any) -> bool:
    return isinstance(value, str) and _DIGEST_RE.fullmatch(value) is not None


def _validated_request(request: Any) -> dict[str, str]:
    """Validate one checkpoint request and return a fresh dict in record order."""
    if not isinstance(request, dict):
        raise TypeError("request must be a dict")
    if set(request.keys()) != set(_REQUEST_KEYS):
        raise ValueError(
            "request must contain exactly the keys 'id', 'state', 'audit' "
            "and 'stage'"
        )
    for key in _REQUEST_KEYS:
        if not isinstance(request[key], str):
            raise TypeError(f"request {key} must be a str")
    checkpoint_id = request[ID]
    if _ID_RE.fullmatch(checkpoint_id) is None:
        raise ValueError("request id must match [A-Za-z0-9._-]{1,64}")
    if not _is_digest(request[STATE]):
        raise ValueError("request state must be 64 lowercase hex characters")
    if not _is_digest(request[AUDIT]):
        raise ValueError("request audit must be 64 lowercase hex characters")
    stage = request[STAGE]
    if stage not in _STAGE_RANK:
        raise ValueError(
            "request stage must be one of 'prepared', 'state', 'audit' or "
            "'committed'"
        )
    return {
        AUDIT: request[AUDIT],
        ID: checkpoint_id,
        STAGE: stage,
        STATE: request[STATE],
    }


def _serialize_index(records: list[dict[str, str]]) -> bytes:
    ordered = [
        {AUDIT: record[AUDIT], ID: record[ID], STAGE: record[STAGE],
         STATE: record[STATE]}
        for record in records
    ]
    index = {ITEMS: ordered, VERSION: _INDEX_VERSION}
    text = json.dumps(index, ensure_ascii=False, separators=(",", ":")) + "\n"
    return text.encode("utf-8")


def _parse_index(raw: bytes) -> list[dict[str, str]]:
    """Validate every byte of a checkpoint index and return its records.

    Raises :class:`CorruptTransactionError` for any UTF-8/JSON failure,
    non-canonical byte encoding, wrong key set or order, bad version,
    duplicate or unsorted ids, or a field that is not a well-formed str.
    """
    if raw == b"":
        raise CorruptTransactionError("checkpoint index is empty")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptTransactionError("checkpoint index is not valid UTF-8") from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise CorruptTransactionError("checkpoint index is not valid JSON") from exc

    if not isinstance(data, dict):
        raise CorruptTransactionError("checkpoint index must be a JSON object")
    if set(data.keys()) != set(_INDEX_KEYS):
        raise CorruptTransactionError(
            "checkpoint index must contain exactly the keys 'items' and 'version'"
        )
    if list(data.keys()) != list(_INDEX_KEYS):
        raise CorruptTransactionError(
            "checkpoint index keys must be in the order 'items', 'version'"
        )
    version = data[VERSION]
    # bool is a subclass of int; the version must be a genuine integer.
    if isinstance(version, bool) or not isinstance(version, int) or version != 1:
        raise CorruptTransactionError("checkpoint index version must be the integer 1")
    raw_items = data[ITEMS]
    if not isinstance(raw_items, list):
        raise CorruptTransactionError("checkpoint index items must be an array")

    records: list[dict[str, str]] = []
    for position, item in enumerate(raw_items):
        where = f"checkpoint index item {position}"
        if not isinstance(item, dict):
            raise CorruptTransactionError(f"{where} must be a JSON object")
        if set(item.keys()) != set(_RECORD_KEYS):
            raise CorruptTransactionError(
                f"{where} must contain exactly the keys 'audit', 'id', 'stage' "
                "and 'state'"
            )
        if list(item.keys()) != list(_RECORD_KEYS):
            raise CorruptTransactionError(
                f"{where} keys must be in the order 'audit', 'id', 'stage', 'state'"
            )
        audit_digest = item[AUDIT]
        record_id = item[ID]
        stage = item[STAGE]
        state_digest = item[STATE]
        if not isinstance(record_id, str) or _ID_RE.fullmatch(record_id) is None:
            raise CorruptTransactionError(f"{where} has an invalid id")
        if not isinstance(stage, str) or stage not in _STAGE_RANK:
            raise CorruptTransactionError(f"{where} has an invalid stage")
        if not isinstance(state_digest, str) or not _is_digest(state_digest):
            raise CorruptTransactionError(
                f"{where} state must be 64 lowercase hex characters"
            )
        if not isinstance(audit_digest, str) or not _is_digest(audit_digest):
            raise CorruptTransactionError(
                f"{where} audit must be 64 lowercase hex characters"
            )
        records.append(
            {AUDIT: audit_digest, ID: record_id, STAGE: stage, STATE: state_digest}
        )

    ids = [record[ID] for record in records]
    if any(left >= right for left, right in zip(ids, ids[1:])):
        raise CorruptTransactionError(
            "checkpoint index ids must be unique and sorted ascending"
        )

    # Reject stray whitespace, non-canonical escapes, and any encoding that
    # is not the single compact form of the validated structure.
    if _serialize_index(records) != raw:
        raise CorruptTransactionError("checkpoint index is not canonically encoded")
    return records


def _read_index(path: str) -> list[dict[str, str]]:
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return []
    return _parse_index(raw)


def _atomic_write(path: str, payload: bytes) -> None:
    tmp_path = path + ".tmp"
    with open(tmp_path, "wb") as handle:
        handle.write(payload)
        handle.flush()
        os.fsync(handle.fileno())
    try:
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise
    fd = os.open(os.path.dirname(os.path.abspath(path)), os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def _apply(
    path: str, records: list[dict[str, str]], record: dict[str, str]
) -> list[dict[str, str]]:
    """Apply ``record`` to ``records`` and return the resulting record list."""
    for position, existing in enumerate(records):
        if existing[ID] != record[ID]:
            continue
        if (
            existing[STATE] != record[STATE]
            or existing[AUDIT] != record[AUDIT]
        ):
            raise ValueError(
                f"checkpoint id {record[ID]!r} is already bound to different "
                "state or audit digests"
            )
        old_rank = _STAGE_RANK[existing[STAGE]]
        new_rank = _STAGE_RANK[record[STAGE]]
        if new_rank == old_rank:
            # Idempotent replay: no filesystem change.
            return records
        if new_rank < old_rank:
            raise ValueError(
                f"checkpoint id {record[ID]!r} cannot regress from stage "
                f"{existing[STAGE]!r} to {record[STAGE]!r}"
            )
        if new_rank > old_rank + 1:
            raise ValueError(
                f"checkpoint id {record[ID]!r} cannot skip from stage "
                f"{existing[STAGE]!r} to {record[STAGE]!r}"
            )
        updated = list(records)
        updated[position] = record
        _atomic_write(path, _serialize_index(updated))
        return updated

    if record[STAGE] != PREPARED:
        raise ValueError("a new checkpoint id must start at the 'prepared' stage")
    updated = sorted(records + [record], key=lambda entry: entry[ID])
    _atomic_write(path, _serialize_index(updated))
    return updated


def checkpoint(
    path: str, request: dict[str, str] | None = None
) -> list[dict[str, str]]:
    """Record or query a replayable commit checkpoint at ``path``.

    With ``request=None`` this is a pure query returning every checkpoint.
    Otherwise ``request`` must contain exactly the str keys ``id``,
    ``state``, ``audit`` and ``stage``: ``id`` matches
    ``[A-Za-z0-9._-]{1,64}``, ``state`` and ``audit`` are 64 lowercase hex
    characters, and ``stage`` is one of ``prepared``, ``state``, ``audit``
    or ``committed``.

    A new id is inserted at ``prepared``; an existing id with identical
    digests replays idempotently at the same stage or advances one adjacent
    stage.  Changed digests, a stage regression or a skipped stage raise
    :class:`ValueError` and leave the file unchanged.  In every case a
    brand-new list sorted ascending by ``id`` is returned, each element a
    fresh dict with the key order ``audit``, ``id``, ``stage``, ``state``.

    Type violations raise :class:`TypeError`; a bad key set, field format
    or stage migration raises :class:`ValueError`; a corrupt index raises
    :class:`CorruptTransactionError`; other filesystem errors propagate as
    :class:`OSError`.
    """
    if not isinstance(path, str):
        raise TypeError("path must be a str")

    record = _validated_request(request) if request is not None else None
    records = _read_index(path)
    if record is not None:
        records = _apply(path, records, record)

    return [
        {
            AUDIT: record[AUDIT],
            ID: record[ID],
            STAGE: record[STAGE],
            STATE: record[STATE],
        }
        for record in records
    ]

import json
import os
import tempfile
import unittest

from offline_coordination import transaction
from offline_coordination.transaction import CorruptTransactionError, checkpoint

D1 = "a" * 64
D2 = "b" * 64
D3 = "c" * 64
D_BAD_UPPER = "A" * 64
RECORD_KEYS = ("audit", "id", "stage", "state")


def req(rid="x", state=D1, audit=D2, stage="prepared"):
    return {"id": rid, "state": state, "audit": audit, "stage": stage}


def canonical(obj):
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")


class CheckpointRoundTripTest(unittest.TestCase):
    def setUp(self) -> None:
        self.dir = tempfile.mkdtemp()
        self.path = os.path.join(self.dir, "checkpoints.json")

    def write(self, data: bytes) -> None:
        with open(self.path, "wb") as handle:
            handle.write(data)

    def read_raw(self) -> bytes:
        with open(self.path, "rb") as handle:
            return handle.read()

    def test_missing_file_queries_as_empty_index(self) -> None:
        self.assertEqual(checkpoint(self.path), [])

    def test_empty_file_is_corrupt(self) -> None:
        self.write(b"")
        with self.assertRaises(CorruptTransactionError):
            checkpoint(self.path)
        with self.assertRaises(CorruptTransactionError):
            checkpoint(self.path, req())

    def test_query_returns_fresh_list_with_fixed_key_order(self) -> None:
        checkpoint(self.path, req(rid="b"))
        checkpoint(self.path, req(rid="a"))
        result = checkpoint(self.path)
        self.assertEqual([item["id"] for item in result], ["a", "b"])
        for item in result:
            self.assertEqual(tuple(item.keys()), RECORD_KEYS)
        self.assertEqual(
            result[0], {"audit": D2, "id": "a", "stage": "prepared", "state": D1}
        )
        again = checkpoint(self.path)
        self.assertIsNot(result, again)
        self.assertIsNot(result[0], again[0])
        result[0]["stage"] = "mutated"
        self.assertEqual(checkpoint(self.path)[0]["stage"], "prepared")

    def test_write_returns_full_sorted_list(self) -> None:
        checkpoint(self.path, req(rid="b"))
        result = checkpoint(self.path, req(rid="a"))
        self.assertEqual([item["id"] for item in result], ["a", "b"])
        for item in result:
            self.assertEqual(tuple(item.keys()), RECORD_KEYS)

    def test_file_is_canonical_compact_json_with_single_lf(self) -> None:
        checkpoint(self.path, req(rid="a"))
        raw = self.read_raw()
        self.assertEqual(
            raw,
            b'{"items":[{"audit":"' + D2.encode()
            + b'","id":"a","stage":"prepared","state":"' + D1.encode()
            + b'"}],"version":1}\n',
        )
        self.assertTrue(raw.endswith(b"\n"))
        self.assertFalse(raw.endswith(b"\n\n"))

    def test_non_ascii_id_charset_is_rejected_but_index_preserves_utf8(self) -> None:
        # ids cannot be non-ASCII, but the serializer must not escape any
        # non-ASCII that could appear in the file; check canonical bytes.
        checkpoint(self.path, req(rid="a"))
        raw = self.read_raw()
        self.assertNotIn(b"\\u", raw)

    def test_items_sorted_by_id_ascending(self) -> None:
        for rid in ("c", "a", "b.b", "a-1", "A", "0"):
            checkpoint(self.path, req(rid=rid))
        index = json.loads(self.read_raw())
        ids = [item["id"] for item in index["items"]]
        self.assertEqual(ids, ["0", "A", "a", "a-1", "b.b", "c"])
        for item in index["items"]:
            self.assertEqual(tuple(item.keys()), RECORD_KEYS)
        self.assertEqual(tuple(index.keys()), ("items", "version"))
        self.assertEqual(index["version"], 1)
        self.assertIsInstance(index["version"], int)

    def test_tmp_file_removed_after_write(self) -> None:
        checkpoint(self.path, req())
        self.assertFalse(os.path.exists(self.path + ".tmp"))


class CheckpointLifecycleTest(unittest.TestCase):
    def setUp(self) -> None:
        self.dir = tempfile.mkdtemp()
        self.path = os.path.join(self.dir, "checkpoints.json")

    def read_raw(self) -> bytes:
        with open(self.path, "rb") as handle:
            return handle.read()

    def test_new_id_must_start_prepared(self) -> None:
        for stage in ("state", "audit", "committed"):
            with self.assertRaises(ValueError, msg=f"stage={stage}"):
                checkpoint(self.path, req(rid=f"new-{stage}", stage=stage))
        self.assertEqual(checkpoint(self.path), [])

    def test_adjacent_stages_advance_in_order(self) -> None:
        checkpoint(self.path, req(stage="prepared"))
        for stage in ("state", "audit", "committed"):
            result = checkpoint(self.path, req(stage=stage))
            self.assertEqual(result[0]["stage"], stage)
        self.assertEqual(checkpoint(self.path)[0]["stage"], "committed")

    def test_same_id_same_digests_same_stage_is_idempotent(self) -> None:
        checkpoint(self.path, req())
        raw = self.read_raw()
        result = checkpoint(self.path, req())
        self.assertEqual(result[0]["stage"], "prepared")
        self.assertEqual(self.read_raw(), raw)
        # Idempotent replay also holds at a later stage.
        checkpoint(self.path, req(stage="state"))
        raw = self.read_raw()
        checkpoint(self.path, req(stage="state"))
        self.assertEqual(self.read_raw(), raw)

    def test_idempotent_replay_accepts_input_in_any_key_order(self) -> None:
        checkpoint(self.path, req(rid="k"))
        raw = self.read_raw()
        again = checkpoint(
            self.path, {"stage": "prepared", "audit": D2, "id": "k", "state": D1}
        )
        self.assertEqual(tuple(again[0].keys()), RECORD_KEYS)
        self.assertEqual(self.read_raw(), raw)

    def test_same_id_different_state_rejected_and_file_untouched(self) -> None:
        checkpoint(self.path, req(state=D1))
        raw = self.read_raw()
        with self.assertRaises(ValueError):
            checkpoint(self.path, req(state=D3))
        self.assertEqual(self.read_raw(), raw)

    def test_same_id_different_audit_rejected_and_file_untouched(self) -> None:
        checkpoint(self.path, req(audit=D2))
        raw = self.read_raw()
        with self.assertRaises(ValueError):
            checkpoint(self.path, req(audit=D3))
        self.assertEqual(self.read_raw(), raw)

    def test_digest_change_rejected_even_with_valid_stage_advance(self) -> None:
        checkpoint(self.path, req())
        raw = self.read_raw()
        with self.assertRaises(ValueError):
            checkpoint(self.path, req(state=D3, stage="state"))
        self.assertEqual(self.read_raw(), raw)

    def test_stage_regression_rejected_and_file_untouched(self) -> None:
        checkpoint(self.path, req())
        checkpoint(self.path, req(stage="state"))
        raw = self.read_raw()
        with self.assertRaises(ValueError):
            checkpoint(self.path, req(stage="prepared"))
        self.assertEqual(self.read_raw(), raw)

    def test_stage_skip_rejected_and_file_untouched(self) -> None:
        checkpoint(self.path, req())
        raw = self.read_raw()
        with self.assertRaises(ValueError):
            checkpoint(self.path, req(stage="audit"))
        with self.assertRaises(ValueError):
            checkpoint(self.path, req(stage="committed"))
        self.assertEqual(self.read_raw(), raw)

    def test_cannot_advance_past_committed(self) -> None:
        checkpoint(self.path, req())
        for stage in ("state", "audit", "committed"):
            checkpoint(self.path, req(stage=stage))
        raw = self.read_raw()
        # Same stage replays fine; there is no further stage to reach.
        checkpoint(self.path, req(stage="committed"))
        self.assertEqual(self.read_raw(), raw)

    def test_rejection_does_not_block_other_ids(self) -> None:
        checkpoint(self.path, req(rid="k"))
        with self.assertRaises(ValueError):
            checkpoint(self.path, req(rid="k", stage="committed"))
        checkpoint(self.path, req(rid="other"))
        self.assertEqual(
            [item["id"] for item in checkpoint(self.path)], ["k", "other"]
        )


class CheckpointValidationTest(unittest.TestCase):
    def setUp(self) -> None:
        self.dir = tempfile.mkdtemp()
        self.path = os.path.join(self.dir, "checkpoints.json")

    def test_path_must_be_str(self) -> None:
        with self.assertRaises(TypeError):
            checkpoint(1)
        with self.assertRaises(TypeError):
            checkpoint(None, req())

    def test_request_must_be_dict_or_none(self) -> None:
        for bad in ([], "x", 1, True):
            with self.assertRaises(TypeError, msg=f"request={bad!r}"):
                checkpoint(self.path, bad)

    def test_request_fields_must_be_str(self) -> None:
        for key in ("id", "state", "audit", "stage"):
            with self.assertRaises(TypeError, msg=f"key={key}"):
                checkpoint(self.path, {**req(), key: 1})

    def test_request_key_set_must_match_exactly(self) -> None:
        with self.assertRaises(ValueError):
            checkpoint(self.path, {"id": "x", "state": D1, "audit": D2})
        with self.assertRaises(ValueError):
            checkpoint(self.path, {**req(), "extra": "x"})

    def test_id_format(self) -> None:
        for good in ("a", "A", "0", ".", "_", "-", "x.y-z_0", "A" * 64):
            result = checkpoint(self.path, req(rid=good))
            self.assertEqual(
                next(item for item in result if item["id"] == good)["id"], good
            )
        for bad in ("", "A" * 65, "a/b", "a b", "a:b", "☃", "a\n", ". "):
            with self.assertRaises(ValueError, msg=f"id={bad!r}"):
                checkpoint(self.path, req(rid=bad))

    def test_digest_format(self) -> None:
        for key in ("state", "audit"):
            for bad in ("a" * 63, "a" * 65, D_BAD_UPPER, "g" * 64):
                with self.assertRaises(ValueError, msg=f"{key}={bad!r}"):
                    checkpoint(self.path, req(**{key: bad}))

    def test_stage_must_be_allowed(self) -> None:
        for bad in ("", "Prepared", "PREPARED", "commit", "done"):
            with self.assertRaises(ValueError, msg=f"stage={bad!r}"):
                checkpoint(self.path, req(stage=bad))

    def test_corrupt_error_is_value_error(self) -> None:
        self.assertTrue(issubclass(CorruptTransactionError, ValueError))


class CheckpointCorruptionTest(unittest.TestCase):
    def setUp(self) -> None:
        self.dir = tempfile.mkdtemp()
        self.path = os.path.join(self.dir, "checkpoints.json")
        checkpoint(self.path, req(rid="a"))
        checkpoint(self.path, req(rid="b", stage="prepared"))
        checkpoint(self.path, req(rid="b", stage="state"))
        self.good = self.read_raw()

    def write(self, data: bytes) -> None:
        with open(self.path, "wb") as handle:
            handle.write(data)

    def read_raw(self) -> bytes:
        with open(self.path, "rb") as handle:
            return handle.read()

    def assertCorrupt(self, data: bytes) -> None:
        self.write(data)
        with self.assertRaises(CorruptTransactionError):
            checkpoint(self.path)
        with self.assertRaises(CorruptTransactionError):
            checkpoint(self.path, req(rid="c"))

    def test_missing_trailing_lf(self) -> None:
        self.assertCorrupt(self.good[:-1])

    def test_extra_trailing_lf(self) -> None:
        self.assertCorrupt(self.good + b"\n")

    def test_non_canonical_whitespace(self) -> None:
        self.assertCorrupt(self.good.replace(b',"version"', b', "version"', 1))

    def test_non_canonical_unicode_escape(self) -> None:
        self.assertCorrupt(self.good.replace(b'"id":"a"', b'"id":"\\u0061"', 1))

    def test_wrong_top_level_key_order(self) -> None:
        index = json.loads(self.good)
        reordered = {"version": index["version"], "items": index["items"]}
        self.assertCorrupt(canonical(reordered) + b"\n")

    def test_wrong_record_key_order(self) -> None:
        index = json.loads(self.good)
        index["items"] = [
            {"id": item["id"], "state": item["state"],
             "audit": item["audit"], "stage": item["stage"]}
            for item in index["items"]
        ]
        self.assertCorrupt(canonical(index) + b"\n")

    def test_extra_top_level_key(self) -> None:
        index = json.loads(self.good)
        index["extra"] = 2
        self.assertCorrupt(canonical(index) + b"\n")

    def test_missing_top_level_key(self) -> None:
        self.assertCorrupt(b'{"items":[]}\n')
        self.assertCorrupt(b'{"version":1}\n')

    def test_bad_version_values(self) -> None:
        good_index = json.loads(self.good)
        for version in (0, 2, "1", 1.0, True, None):
            bad = dict(good_index)
            bad["version"] = version
            self.assertCorrupt(canonical(bad) + b"\n")

    def test_items_not_array(self) -> None:
        self.assertCorrupt(b'{"items":{},"version":1}\n')

    def test_item_not_object(self) -> None:
        self.assertCorrupt(b'{"items":[1],"version":1}\n')

    def test_extra_record_key(self) -> None:
        index = json.loads(self.good)
        index["items"][0]["extra"] = "x"
        self.assertCorrupt(canonical(index) + b"\n")

    def test_missing_record_key(self) -> None:
        index = json.loads(self.good)
